// Claude's task tools as a plan source (pure): the payloads of TaskCreate, TaskUpdate and TodoWrite
// folded into one list, the task files a resume rebuilds it from, and the list as a plan. SPEC.md 4.5.
import type { Plan, Status, Task } from './plan.ts'
import { clean, TASKS_MAX, TITLE_MAX } from './format.ts'
import { buildPlan } from './planbuild.ts'

export interface TaskItem {
  id: string
  title: string
  status: Status
  at?: number // when a call last added or changed it (SPEC 4.1: newer data than a finished list above)
}

// The tools' status words as the plan's: pending open, in_progress partial, completed done.
const STATUS: Record<string, Status> = { pending: 'open', in_progress: 'partial', completed: 'done' }

function asRecord(v: unknown): Record<string, unknown> {
  return typeof v === 'object' && v !== null ? (v as Record<string, unknown>) : {}
}

function text(v: unknown): string | undefined {
  return typeof v === 'string' && v !== '' ? v : undefined
}

// A title as it is taken in: one clean line of at most TITLE_MAX characters (SPEC 12); none when empty.
function titleOf(v: unknown): string | undefined {
  const t = typeof v === 'string' ? clean(v, TITLE_MAX) : ''
  return t !== '' ? t : undefined
}

// A call that failed (a string result, `success: false`) changed nothing in the engine's list either.
function failed(output: unknown): boolean {
  return typeof output !== 'object' || output === null || asRecord(output).success === false
}

const stamp = (at: number | undefined) => (at !== undefined ? { at } : {})

function created(list: TaskItem[] | null, input: Record<string, unknown>, output: unknown, at?: number): TaskItem[] | null {
  const id = text(asRecord(asRecord(output).task).id)
  const title = titleOf(input.subject)
  if (failed(output) || id === undefined || title === undefined) return list
  const items = list ?? []
  // an id already listed is the same task: renamed, in its place, status kept
  if (items.some((t) => t.id === id)) return items.map((t) => (t.id === id ? { ...t, title, ...stamp(at) } : t))
  // a full list takes no more
  if (items.length >= TASKS_MAX) return list
  return [...items, { id, title, status: 'open', ...stamp(at) }]
}

function updated(list: TaskItem[] | null, input: Record<string, unknown>, output: unknown, at?: number): TaskItem[] | null {
  const id = text(input.taskId)
  if (list === null || failed(output) || id === undefined || !list.some((t) => t.id === id)) return list
  if (input.status === 'deleted') return list.filter((t) => t.id !== id)
  const status = typeof input.status === 'string' ? STATUS[input.status] : undefined
  const title = titleOf(input.subject)
  return list.map((t) => (t.id === id ? { ...t, ...(title !== undefined ? { title } : {}), ...(status !== undefined ? { status } : {}), ...stamp(at) } : t))
}

// A TodoWrite row's id: a short hash of its content, lower-cased with its spacing collapsed, so a row
// keeps its id when rows are inserted, dropped or reordered around it (SPEC 4.5).
export function todoId(content: string): string {
  let h = 0x811c9dc5
  for (const ch of content.trim().replace(/\s+/g, ' ').toLowerCase()) {
    h ^= ch.codePointAt(0)!
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return (h % 36 ** 4).toString(36).padStart(4, '0')
}

// The whole list, every call: its rows in order, each id from its content, a repeat of the same
// content told apart by `-2`, `-3`. The input names the list even when the engine empties its own
// once every row is done. A row keeps its stamp unless it is new or its status moved.
function written(list: TaskItem[] | null, input: Record<string, unknown>, output: unknown, at?: number): TaskItem[] | null {
  if (!Array.isArray(input.todos) || typeof output === 'string') return list
  const seen = new Map<string, number>()
  const out: TaskItem[] = []
  for (const raw of input.todos as unknown[]) {
    if (out.length >= TASKS_MAX) break
    const r = asRecord(raw)
    const title = titleOf(r.content)
    if (title === undefined) continue
    const status = (typeof r.status === 'string' ? STATUS[r.status] : undefined) ?? 'open'
    const base = todoId(title)
    const n = (seen.get(base) ?? 0) + 1
    seen.set(base, n)
    const id = n === 1 ? base : base + '-' + n
    const was = list?.find((t) => t.id === id)
    out.push({ id, title, status, ...(was !== undefined && was.status === status ? stamp(was.at) : stamp(at)) })
  }
  return out
}

// The list after one call of the main loop. `input` is the call's fields, `output` the tool's result.
// Any other tool (TaskList, TaskGet, ...) leaves the list as it is.
// `at`: the call's time, stamped on each item it adds or changes.
export function applyTaskCall(tool: string, input: Record<string, unknown>, output: unknown, list: TaskItem[] | null, at?: number): TaskItem[] | null {
  if (tool === 'TaskCreate') return created(list, input, output, at)
  if (tool === 'TaskUpdate') return updated(list, input, output, at)
  if (tool === 'TodoWrite') return written(list, input, output, at)
  return list
}

// One task file of `<configDir>/tasks/<session_id>/` (`{ id, subject, status, ... }`); null for
// anything else (the lock, a deleted task, text that is not a task).
export function parseTaskFile(raw: string): TaskItem | null {
  let o: Record<string, unknown>
  try {
    o = asRecord(JSON.parse(raw))
  } catch {
    return null
  }
  const id = text(o.id)
  const title = titleOf(o.subject)
  const status = typeof o.status === 'string' ? STATUS[o.status] : undefined
  return id === undefined || title === undefined || status === undefined ? null : { id, title, status }
}

// The list the task files hold, ids in numeric order; null when none is a task.
export function rebuildFromFiles(files: string[]): TaskItem[] | null {
  const items = files.flatMap((f) => parseTaskFile(f) ?? [])
  items.sort((a, b) => a.id.localeCompare(b.id, 'en', { numeric: true }))
  return items.length > 0 ? items.slice(0, TASKS_MAX) : null
}

// The list as a plan: one group of its own, every task in it.
export function tasksPlan(items: TaskItem[]): Plan {
  const tasks: Task[] = items.map((t, i) => ({ id: t.id, title: t.title, ordinal: i + 1, line: 0, shape: 'checklist', status: t.status, groups: [0] }))
  return buildPlan({ section: '', tasks, groups: [{ id: 'tasks', title: '', kind: 'heading', own: true, tasks: tasks.map((_, i) => i) }] })
}

files.hooks/sources.ts:
// Plan sources (pure): which source draws the goal, its tag, its plan and its label. SPEC.md 4.1, 4.8.
//
// The seam. `SOURCES` is the precedence, highest first; the first row whose `has` is true is the
// active source. A source is one row here plus the hook in register.tsx that writes its data into
// `Sources`:
//   - P2 (report updates, partial) changed the `reported` row's data, `reportPlan`, `applyReport` and the
//     `temporal` flag (rows a task-less agent may attach to by its one partial task, 5.3); nothing else;
//   - P3 (task tools) adds a `tasks` field to `Sources`, a `tasks` row after `plan`, clears it in
//     `approvePlan`;
//   - P4 (workflow phases) adds a `phases` row after it the same way.
// register.tsx reads the active tag and plan only through `activeSource` and `sourcePlan`, so
// nothing else changes when a row is added. The file row has no `plan`: its plan is read and
// re-read by the 2 s poll (register.tsx loadPlan), which owns the file's mtime and its errors.
import type { Filter } from './pin.ts'
import { absolutePath } from './pin.ts'
import type { Plan, Task } from './plan.ts'
import type { PlanMode } from './planmode.ts'
import { phasePlan } from './phases.ts'
import type { PhaseRun } from './phases.ts'
import { applyUpdates, reportPlan } from './tool.ts'
import type { Reported, StatusUpdate } from './tool.ts'
import { basename, clean, TITLE_MAX, truncate } from './format.ts'
import { planFlips } from './agents.ts'
import { boundPlan, buildPlan } from './planbuild.ts'
import type { LogEntry } from './agents.ts'
import { tasksPlan } from './tasks.ts'
import type { TaskItem } from './tasks.ts'

export type SourceTag = 'file' | 'reported' | 'plan' | 'tasks' | 'phases'

// The data of every source, whether or not it is the one drawn: a lower source keeps its data
// while a higher one is active.
export interface Sources {
  filter: Filter | null
  report: Reported | null
  planMode: PlanMode | null
  tasks: TaskItem[] | null
  phases: PhaseRun | null // derived from the agent records on every read (phases.ts), never stored
}

interface SourceRow {
  tag: SourceTag
  has: (s: Sources) => boolean
  plan?: (s: Sources) => Plan // in-memory sources only
  title?: (s: Sources) => string | undefined // the source's own goal label, before the prompt's
  temporal?: true // an agent that names no task joins the one partial task (SPEC 5.3)
  doneAt?: (s: Sources) => number | undefined // a list whose every task is done: when it got there
  dataAt?: (s: Sources) => number | undefined // when the source's data last moved
}

export const SOURCES: SourceRow[] = [
  { tag: 'file', has: (s) => s.filter !== null, title: (s) => s.filter!.section ?? basename(s.filter!.file) },
  { tag: 'reported', has: (s) => (s.report?.tasks.length ?? 0) > 0, plan: (s) => reportPlan(s.report!), title: (s) => s.report!.title, temporal: true, doneAt: (s) => s.report!.doneAt },
  { tag: 'plan', has: (s) => (s.planMode?.steps.length ?? 0) > 0, plan: (s) => modePlan(s.planMode!), title: (s) => s.planMode!.title, temporal: true, doneAt: (s) => s.planMode!.doneAt },
  { tag: 'tasks', has: (s) => (s.tasks?.length ?? 0) > 0, plan: (s) => tasksPlan(s.tasks!), temporal: true, dataAt: (s) => Math.max(...s.tasks!.map((t) => t.at ?? -Infinity)) },
  { tag: 'phases', has: (s) => s.phases !== null, plan: (s) => phasePlan(s.phases!), title: (s) => s.phases!.title, dataAt: (s) => s.phases!.at },
]

// 4.1: a list whose every task is done yields to a lower source whose data moved after it finished.
function yields(s: Sources, i: number): boolean {
  const done = SOURCES[i].doneAt?.(s)
  return done !== undefined && SOURCES.slice(i + 1).some((r) => r.has(s) && (r.dataAt?.(s) ?? -Infinity) > done)
}

export function activeSource(s: Sources): SourceTag | null {
  return SOURCES.find((r, i) => r.has(s) && !yields(s, i))?.tag ?? null
}

// A reported or plan-mode list after a change: stamped with the moment its every task became done
// (kept while it stays so), unstamped while one is not.
export function withDoneAt<T extends { doneAt?: number }>(src: T, items: Array<{ status: string }>, at: number): T {
  const { doneAt, ...rest } = src
  const all = items.length > 0 && items.every((t) => t.status === 'done')
  return (all ? { ...rest, doneAt: doneAt ?? at } : rest) as T
}

// 5.3 step 2 applies to this source's plan.
export function isTemporal(tag: SourceTag | null): boolean {
  return SOURCES.find((r) => r.tag === tag)?.temporal === true
}

// 4.3: `report` updates move the tasks of the active source when it is a reported or plan-mode list;
// any other active source (or none) refuses them. Answers the sources with the moved list.
export function applyReport(
  s: Sources,
  updates: StatusUpdate[],
  at: number,
): { ok: true; sources: Sources; applied: number; unknown: string[] } | { ok: false; error: string } {
  const tag = activeSource(s)
  if (tag === 'reported') {
    const r = applyUpdates(s.report!.tasks, updates)
    return { ok: true, sources: { ...s, report: withDoneAt({ ...s.report!, tasks: r.items }, r.items, at) }, applied: r.applied, unknown: r.unknown }
  }
  if (tag === 'plan') {
    const r = applyUpdates(s.planMode!.steps, updates)
    return { ok: true, sources: { ...s, planMode: withDoneAt({ ...s.planMode!, steps: r.items }, r.items, at) }, applied: r.applied, unknown: r.unknown }
  }
  return { ok: false, error: 'updates apply to a reported or plan-mode list' }
}

// The plan an in-memory source stands for; null for the file (the poll's parse) and for no source.
export function sourcePlan(s: Sources, tag: SourceTag | null): Plan | null {
  const row = SOURCES.find((r) => r.tag === tag)
  return row?.plan && row.has(s) ? boundPlan(row.plan(s)) : null
}

// 4.8: the source's own title, else the prompt line of the turn that started it, else the tag itself.
export function goalLabel(s: Sources, tag: SourceTag, prompt: string | null | undefined): string {
  const own = SOURCES.find((r) => r.tag === tag)?.title?.(s)
  const text = own === undefined ? '' : clean(own, TITLE_MAX)
  if (text !== '') return text
  return prompt ?? tag
}

// 4.1: an approval starts a new piece of work. It replaces the plan-mode plan (a plan with no step
// leaves the source empty) and clears the reported list and the task-tool list; the pinned file is not touched.
export function approvePlan(s: Sources, planMode: PlanMode): Sources {
  return { ...s, report: null, tasks: null, planMode: planMode.steps.length > 0 ? planMode : null }
}

// A plan-mode plan as a plan: its steps as tasks under their heading groups, children as each bar.
export function modePlan(pm: PlanMode): Plan {
  const tasks: Task[] = pm.steps.map((st, i) => ({
    id: st.id,
    title: st.title,
    ordinal: i + 1,
    line: 0,
    shape: 'checklist',
    status: st.status,
    groups: [st.group],
    // a done step's children are done with it
    ...(st.sub ? { sub: st.status === 'done' ? { done: st.sub.total, total: st.sub.total } : { ...st.sub } } : {}),
  }))
  return buildPlan({
    section: pm.title ?? '',
    tasks,
    groups: pm.groups.map((g, gi) => ({ id: g.id, title: g.title, kind: 'heading' as const, ...(g.own ? { own: true as const } : {}), tasks: tasks.flatMap((t, ti) => (t.groups[0] === gi ? [ti] : [])) })),
    partialWord: true,
  })
}

// 4.8: each in-memory source's prompt label, the newest qualifying prompt at the moment the source
// started (a full report list, a plan approval, a task list out of nothing, a new run with phases).
// A later prompt never renames it; the next start of the same source does.
export type SourceLabels = Partial<Record<SourceTag, string>>

export function startLabel(labels: SourceLabels, tag: SourceTag, prompt: string | null): SourceLabels {
  const out: SourceLabels = { ...labels }
  if (prompt === null) delete out[tag]
  else out[tag] = prompt
  return out
}

// The task flips of one in-memory source between two of its states, in the words every source uses
// (SPEC 8: each `task-done` is a task boundary). The file's own flips add "(plan changed)".
export function sourceFlips(prev: Plan, next: Plan, at: number): LogEntry[] {
  return planFlips(prev, next, at, '')
}

const LABEL_MAX = 60

// The text without its `<pasted_content ...>` and `</pasted_content>` tags: a tag runs to the first `>`
// after its name, and with no `>` left there is no tag left. One pass; a pattern with `[^>]*` would
// rescan the rest of the prompt from every unclosed `<pasted_content`.
function withoutPasteTags(text: string): string {
  let out = ''
  let at = 0
  let from = 0
  for (;;) {
    const lt = text.indexOf('<', from)
    if (lt < 0) break
    const name = lt + (text[lt + 1] === '/' ? 2 : 1)
    const end = name + 'pasted_content'.length
    if (!text.startsWith('pasted_content', name) || /\w/.test(text[end] ?? ' ')) {
      from = lt + 1
      continue
    }
    const close = text.indexOf('>', end)
    if (close < 0) break
    out += text.slice(at, lt)
    at = close + 1
    from = at
  }
  return out + text.slice(at)
}

// The label a `prompt.submit` gives (4.8): a composer prompt that is not a slash command, its
// pasted-content tags removed (the pasted text stays), the first non-empty line, cut to 60.
export function promptLabel(text: string, originKind: string | undefined): string | undefined {
  if (originKind !== 'composer' || typeof text !== 'string') return undefined
  if (text.trimStart().startsWith('/')) return undefined
  const line = withoutPasteTags(text)
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((l) => clean(l))
    .find((l) => l !== '')
  return line === undefined ? undefined : truncate(line, LABEL_MAX)
}

// 4.1: a full `report` list is new work, which retires the finished agents, when fewer than half of
// its tasks share an id and a title (any case, spacing collapsed) with the list it replaces.
export function isNewWork(old: Reported | null, next: Reported): boolean {
  const key = (t: { id: string; title: string }) => t.id + '\u0000' + t.title.toLowerCase().replace(/\s+/g, ' ').trim()
  const before = new Set((old?.tasks ?? []).map(key))
  const shared = next.tasks.filter((t) => before.has(key(t))).length
  return shared < next.tasks.length / 2
}

// 4.4: a tool `track` names the plan-mode plan's file when its path, normalised, is the approved
// plan's own; a Windows-style path (`C:\...`) compares in any case, as its filesystem does.
export function isPlanModeFile(file: string, approved: string | undefined): boolean {
  if (approved === undefined) return false
  const key = (p: string) => {
    const abs = absolutePath('/', p)
    return abs.startsWith('/') ? abs : abs.toLowerCase()
  }
  return key(file) === key(approved)
}

files.hooks/prices.ts:
// The one price table and costOf (pure). SPEC.md section 6. Per-agent costs are estimates: the
// session figure comes exact from `$.session.usage()`.

// Prices: USD per million tokens, from the claude-api skill bundled with Claude Code 2.1.296 (the
// skill's table cached 2026-10-06). Columns: input, output, cache read, cache write 5m, cache
// write 1h. Order matters: the first row whose regex matches wins, so the most specific family
// comes first (opus-5-5 before opus-5, fable-5-1 before fable-5). A model id the table does not
// name falls back to the sonnet-5-5 row (the current Sonnet) and is marked unknown (`est.?`).
// Shown after the agents sum on the Usage tab.
export const PRICES_NOTE = 'prices as of 2026-10-06'

export type Row = [input: number, output: number, cacheRead: number, cacheWrite5m: number, cacheWrite1h: number]

// The trailing group ends a family at a digit boundary: opus-5 does not take opus-5-5 or opus-50.
const END = '(?![0-9])'

const TABLE: Array<[RegExp, Row]> = [
  [new RegExp('(?:fable|mythos)-5-1' + END), [10, 50, 0.25, 12.5, 20]],
  [new RegExp('(?:fable|mythos)-5' + END), [10, 50, 1.0, 12.5, 20]],
  [new RegExp('opus-5-5' + END), [4, 20, 0.2, 5, 8]],
  [new RegExp('opus-5' + END), [5, 25, 0.5, 6.25, 10]],
  [new RegExp('opus-4-[678]' + END), [5, 25, 0.5, 6.25, 10]],
  [new RegExp('sonnet-5-5' + END), [2, 10, 0.2, 2.5, 4]],
  [new RegExp('sonnet-5' + END), [2, 10, 0.2, 2.5, 4]],
  [new RegExp('sonnet-4-6' + END), [3, 15, 0.3, 3.75, 6]],
  [new RegExp('haiku-5-5' + END), [0.1, 0.5, 0.01, 0.125, 0.2]],
  [new RegExp('haiku-4-5' + END), [1, 5, 0.1, 1.25, 2]],
]

const FALLBACK: Row = [2, 10, 0.2, 2.5, 4]

// haiku-5-5: a step whose prompt exceeds 100K tokens is billed 0.50 input and 2.50 output.
const HAIKU_LONG = { family: new RegExp('haiku-5-5' + END), above: 100_000, input: 0.5, output: 2.5 }

// opus-5-5 in fast mode (`usage.speed === 'fast'`) costs twice the standard rate.
const FAST_DOUBLE = new RegExp('opus-5-5' + END)

export interface PriceUsage {
  input_tokens?: number | null
  output_tokens?: number | null
  cache_read_input_tokens?: number | null
  cache_creation_input_tokens?: number | null
  cache_creation?: { ephemeral_5m_input_tokens?: number | null; ephemeral_1h_input_tokens?: number | null } | null
  speed?: string | null
  model?: string
}

export interface Cost {
  usd: number
  known: boolean // the model id is a row of the table; false means the sonnet fallback (`est.?`)
  writeAssumed: boolean // cache writes had no 5m/1h split and were priced at the 1h rate
}

const rowOf = (model: string | undefined): Row | undefined => {
  const m = (model ?? '').toLowerCase()
  for (const [re, row] of TABLE) if (re.test(m)) return row
  return undefined
}

// The table's family for a model id, or undefined when the table has no row for it.
export function priceFamily(model: string | undefined): string | undefined {
  const m = (model ?? '').toLowerCase()
  for (const [re] of TABLE) {
    const hit = re.exec(m)
    if (hit) return hit[0]
  }
  return undefined
}

// One response's (or one turn's) cost. `usage.model`, the id the API answered with, is preferred to
// the caller's `model`. Cache writes use the 5m/1h split when the usage carries it; otherwise the
// whole write is priced at the 1h rate, the TTL these accounts run, and `writeAssumed` is set.
export function costOf(model: string | undefined, usage: PriceUsage): Cost {
  const id = usage.model ?? model
  const row = rowOf(id)
  const [pIn, pOut, pRead, p5m, p1h] = row ?? FALLBACK
  const n = (v: number | null | undefined) => (typeof v === 'number' && v > 0 ? v : 0)
  const input = n(usage.input_tokens)
  const read = n(usage.cache_read_input_tokens)
  const split = usage.cache_creation
  const w5m = split ? n(split.ephemeral_5m_input_tokens) : 0
  const w1h = split ? n(split.ephemeral_1h_input_tokens) : n(usage.cache_creation_input_tokens)
  const write = split ? w5m + w1h : w1h
  let rateIn = pIn
  let rateOut = pOut
  if (HAIKU_LONG.family.test((id ?? '').toLowerCase()) && input + read + write > HAIKU_LONG.above) {
    rateIn = HAIKU_LONG.input
    rateOut = HAIKU_LONG.output
  }
  let usd = (input * rateIn + n(usage.output_tokens) * rateOut + read * pRead + w5m * p5m + w1h * p1h) / 1_000_000
  if (usage.speed === 'fast' && FAST_DOUBLE.test((id ?? '').toLowerCase())) usd *= 2
  return { usd, known: row !== undefined, writeAssumed: !split && write > 0 }
}

